def drawerGridsPositiveProofStrip(drawers):
    a=drawers
    out=[]
    for row in a: out.append(sum(row))
    return [x for x in out if x>0]


java
class Solution {
  public int[] drawerGridsPositiveProofStrip(int[][] drawers) {
    int[][] a=drawers; List<Integer> out=new ArrayList<>();
    {for(int[]row:a){int s=0;for(int x:row)s+=x;out.add(s);}}
    return out.stream().filter(x->x>0).mapToInt(Integer::intValue).toArray();
  }
}
